with base as (select *, case when city = 'Berlin' then 1 else 0 end as is_berlin, coalesce(segment, 'DIRECT') as segment_clean from customers where segment = 'Corporate'), latest_match as (select s.*, latest.subscription_start_date, latest.status from base s left join lateral (select c.start_date as subscription_start_date, c.status from subscriptions c where c.customer_id = s.id and c.end_date <= s.signup_date order by c.end_date desc, c.id desc limit 1) latest on true), with_last as (select s.id, s.city, s.segment, s.is_active, s.credit_limit, s.age, s.is_berlin, s.segment_clean, s.subscription_start_date, x.order_status, x.order_shipping_fee from latest_match s left join lateral (select c.status as order_status, c.shipping_fee as order_shipping_fee from orders c where c.customer_id = s.id order by c.shipping_fee desc, c.id desc limit 1) x on true), latest as (select * from (select *, rank() over (partition by segment, order_status order by age desc) as dedup_rank from with_last) ranked where dedup_rank = 1) select date_trunc('week', subscription_start_date) as week_start, avg(order_shipping_fee) as avg_order_shipping_fee, bit_or(age) as age_bit_or, count_if(city = 'Berlin') as berlin_events, bit_or(age) as age_bit_or_2, sort_array(collect_set(city)) as city_list from latest group by 1;
